INSERT INTO "strategies" ("id", "slug", "name", "description", "kind", "status", "source_ref", "tags", "section", "params") VALUES
  ('strategy-seed-post-earnings-strength-radar', 'post-earnings-strength-radar', 'Post-Earnings Strength Radar', 'Weekly list of $2B+ stocks that beat EPS, grew revenue year on year and gained 3%+ on 1.5x volume after the report, holding above the pre-report close and the 50/200-day averages. Alert: a trade through the reaction-day high, or a fresh 52-week high. Backtest not run: needs an earnings data source. Spec: docs/specs/strategies/post-earnings-strength-radar.md. Rules restated from https://freestockalerts.ai/templates/post-earnings-strength-radar. Research only.', 'python', 'researching', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","earnings","needs-data"]'::jsonb, 'Idea discovery', '[]'::jsonb),
  ('strategy-seed-quality-breakout-radar', 'quality-breakout-radar', 'Quality Breakout Radar', 'Monthly list of $5B+ stocks with positive free cash flow, growth and net debt under 3x EBITDA, above the 50/200-day averages and within 5% of the 52-week high. Alert: a fresh 52-week high. Price-rule backtest 2006-2026: fail (20-day excess -0.20% vs universe, both halves negative). Spec: docs/specs/strategies/quality-breakout-radar.md. Rules restated from https://freestockalerts.ai/templates/quality-breakout-radar. Research only.', 'python', 'backtested', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","breakout","52-week-high"]'::jsonb, 'Idea discovery', '[]'::jsonb),
  ('strategy-seed-under-the-radar-breakouts', 'under-the-radar-breakouts', 'Under-the-Radar Breakouts', 'Monthly list of $2B-$20B stocks, profitable with positive free cash flow, above the 50/200-day averages, within 8% of the 52-week high and 30%+ above the low. Alert: a fresh 52-week high. Price-rule backtest 2006-2026: fail (20-day excess -0.18%). Spec: docs/specs/strategies/under-the-radar-breakouts.md. Rules restated from https://freestockalerts.ai/templates/under-the-radar-breakouts. Research only.', 'python', 'backtested', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","breakout","mid-cap"]'::jsonb, 'Idea discovery', '[]'::jsonb),
  ('strategy-seed-insider-purchase-confirmation', 'insider-purchase-confirmation', 'Insider Purchase Confirmation', 'Open-market Form 4 purchases (code P) of $100k+ by directors or senior officers in the last 30 days, price above the 50-day average. Alert after the close: a close above the highest close since the purchase, or within 3% of it on 1.5x volume. 14-day cooldown. Backtest not run: needs an insider-trade data source. Spec: docs/specs/strategies/insider-purchase-confirmation.md. Rules restated from https://freestockalerts.ai/templates/insider-purchase-confirmation. Research only.', 'python', 'researching', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","insider","needs-data"]'::jsonb, 'Idea discovery', '[]'::jsonb),
  ('strategy-seed-analyst-upgrade-clusters', 'analyst-upgrade-clusters', 'Analyst Upgrade Clusters', 'Two or more firms upgrading, or initiating at Buy or better, within 14 days with no cut out of buy territory, price above the 50-day average. Alert after the close: a close above the 20-day high, or 1.5x volume on an up day. 14-day cooldown. Backtest not run: needs an analyst-rating data source. Spec: docs/specs/strategies/analyst-upgrade-clusters.md. Rules restated from https://freestockalerts.ai/templates/analyst-upgrade-clusters. Research only.', 'python', 'researching', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","analyst","needs-data"]'::jsonb, 'Idea discovery', '[]'::jsonb),
  ('strategy-seed-quality-compounders-on-pullback', 'quality-compounders-on-pullback', 'Quality Compounders on Pullback', 'Monthly list of $20B+ non-financial compounders 12-30% below the 52-week high, no more than 8% below the 200-day average and below the 50-day average. Alert: a reclaim of the 50-day average. Price-rule backtest 2006-2026: fail (20-day excess -0.15%). Spec: docs/specs/strategies/quality-compounders-on-pullback.md. Rules restated from https://freestockalerts.ai/templates/quality-compounders-on-pullback. Research only.', 'python', 'backtested', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","pullback","50-day"]'::jsonb, 'Entry timing', '[]'::jsonb),
  ('strategy-seed-leader-pullback-and-reclaim', 'leader-pullback-and-reclaim', 'Leader Pullback and Reclaim', 'Weekly list of $50B+ leaders above the 200-day average, 8-20% below the 52-week high, below the 50-day average with RSI(14) 35-45. Alert: a reclaim of the 50-day average. Price-rule backtest 2006-2026: fail (20-day excess -0.16%). Spec: docs/specs/strategies/leader-pullback-and-reclaim.md. Rules restated from https://freestockalerts.ai/templates/leader-pullback-and-reclaim. Research only.', 'python', 'backtested', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","pullback","rsi"]'::jsonb, 'Entry timing', '[]'::jsonb),
  ('strategy-seed-200-day-comeback-watchlist', '200-day-comeback-watchlist', '200-Day Comeback Watchlist', 'Weekly list of $10B+ stocks below the 200-day average on 40 of the last 60 sessions, within 20% of it, above the 50-day average and 20%+ below the 52-week high. Alert: the first cross above the 200-day average. Price-rule backtest 2006-2026: fail (20-day excess -0.36%). Spec: docs/specs/strategies/200-day-comeback-watchlist.md. Rules restated from https://freestockalerts.ai/templates/200-day-comeback-watchlist. Research only.', 'python', 'backtested', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","200-day","turnaround"]'::jsonb, 'Entry timing', '[]'::jsonb),
  ('strategy-seed-dividend-growth-buy-zones', 'dividend-growth-buy-zones', 'Dividend Growth Buy Zones', 'Monthly list of dividend payers with 5+ years of rising calendar-year dividends and a forward yield of 1.5%+. Alert: the price reaches forward dividend / buy-zone yield (80th percentile of ex-date yields over 5 years), or, when already in the zone, a reclaim of the 200-day average. Price and dividend backtest 2011-2026: fail (20-day excess -0.42%). Spec: docs/specs/strategies/dividend-growth-buy-zones.md. Rules restated from https://freestockalerts.ai/templates/dividend-growth-buy-zones. Research only.', 'python', 'backtested', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","dividend","yield"]'::jsonb, 'Entry timing', '[]'::jsonb),
  ('strategy-seed-sector-leadership-radar', 'sector-leadership-radar', 'Sector Leadership Radar', 'The 11 Select Sector SPDR ETFs. Alert: a cross above the 50-day average, labelled a bounce in a downtrend when the ETF is below its 200-day average and trails SPY over 21 sessions. Backtest 2005-2026: no edge against the other sector ETFs (20-day excess -0.06%). Spec: docs/specs/strategies/sector-leadership-radar.md. Rules restated from https://freestockalerts.ai/templates/sector-leadership-radar. Research only.', 'python', 'backtested', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","sectors","etf"]'::jsonb, 'Monitoring', '[]'::jsonb),
  ('strategy-seed-market-stress-alerts', 'market-stress-alerts', 'Market Stress Alerts', 'VIX above 25, above 35 and below 13; SPY 2% and QQQ 3% session moves; SPY 200-day crosses; IWM 200-day cross below; TLT 2% and HYG 1.5% moves. Context alerts, not trade signals. Backtest of SPY after each alert 2005-2026: no alert passes the frozen rule; VIX below 13 was followed by below-average SPY returns. Spec: docs/specs/strategies/market-stress-alerts.md. Rules restated from https://freestockalerts.ai/templates/market-stress-alerts. Research only.', 'python', 'backtested', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","market","volatility"]'::jsonb, 'Monitoring', '[]'::jsonb),
  ('strategy-seed-earnings-calendar-alerts', 'earnings-calendar-alerts', 'Earnings Calendar Alerts', 'Reminders 3 days before AAPL, NVDA, TSLA, META, AMZN, MSFT and GOOGL report, plus alerts on 5% (AAPL) and 7% (NVDA, TSLA) session moves. Move alerts 2005-2026: excess over the 7-stock average passes, but excess over each stock''s own average return fails (selection effect). Reminders need an earnings-calendar data source. Spec: docs/specs/strategies/earnings-calendar-alerts.md. Rules restated from https://freestockalerts.ai/templates/earnings-calendar-alerts. Research only.', 'python', 'backtested', 'services/research/strategies/alert_templates.py', '["freestockalerts","alerts","daily","earnings","mega-cap"]'::jsonb, 'Monitoring', '[]'::jsonb),
  ('strategy-seed-nicholascrown-sox-macro-checklist', 'nicholascrown-sox-macro-checklist', 'Crown SOX macro checklist (direction filter)', 'Nicholas Crown''s SOX desk checklist used as a long/flat direction filter on SOXX. Backtest code and data are outside this repository (~/Github/tools/crown-sox-filter on the rig). Research only.', 'external', 'backtested', 'docs/specs/strategies/nicholascrown-sox-macro-checklist.md', '["crown","sox","filter","daily"]'::jsonb, 'Macro filters', '[]'::jsonb),
  ('strategy-seed-bridgingcycles-short-strangle', 'bridgingcycles-short-strangle', 'BridgingCycles short strangle', 'Monthly 30-60 DTE short strangle at expected-move strikes when the volatility risk premium percentile is high; 50% target, 2x-credit stop, 21 DTE time stop. Engine and simulator are coded and tested; no historical backtest yet (needs option-chain or implied-volatility history). Research only.', 'python', 'researching', 'services/research/gamma/engines/bridgingcycles_short_strangle.py', '["options","strangle","needs-data"]'::jsonb, 'Options income', '[]'::jsonb),
  ('strategy-seed-151-4-1-sector-momentum-rotation', '151-4-1-sector-momentum-rotation', 'Sector momentum rotation (151 Strategies 4.1)', 'Hold the 2 Select Sector SPDR ETFs with the highest 12-month return, rebalanced monthly; variants with a 200-day MA filter (4.1.1) and a SPY 200-day switch to TLT (4.1.2). Backtest 2006-2026: all three fail (none beats equal-weight sectors in both halves); the variants cut the maximum drawdown. Spec: docs/specs/strategies/151-4-1-sector-momentum-rotation.md. Research only.', 'python', 'backtested', 'services/research/strategies/sector_rotation.py', '["151-strategies","sectors","momentum","monthly"]'::jsonb, '151 Trading Strategies', '[]'::jsonb)
